import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

/**
 * Round-Trip Test: new-user-onboarding-subflow
 *
 * XML Source: sys_hub_flow_fc629d4281d849bd913e1e454cb059bf.xml
 * Fluent Source: new-user-onboarding-subflow.now.ts
 *
 * Subflow Name: New User Onboarding Subflow
 * Description: Handles onboarding tasks with inputs, outputs, and multiple action types
 *
 * Features Tested:
 * - Subflow definition with inputs and outputs
 * - Flow variables (boolean, string)
 * - Multiple action types (lookUpRecord, sendNotification, updateRecord, log)
 * - If/else conditional logic (2 sets)
 * - assignSubflowOutputs
 * - DataPills with different types (reference, string)
 * - TemplateValue usage
 * - XML → Fluent → XML round-trip transformation
 */

/**
 * Helper function to validate imports in generated Fluent code
 * @param content - The Fluent code content to validate
 * @param expectedImports - Array of expected import strings
 */
function validateImports(content: string, expectedImports: string[]) {
    expect(content).toContain('import {')
    expectedImports.forEach((importName) => {
        expect(content).toContain(importName)
    })
}

describe('new-user-onboarding-subflow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Test: new-user-onboarding-subflow
     * XML: sys_hub_flow_fc629d4281d849bd913e1e454cb059bf.xml
     * Type: Subflow
     * Features: Inputs, outputs, flow variables, multiple action types, if/else logic, assignSubflowOutputs
     *
     * SKIPPED: TypeScript diagnostic error - assignSubflowOutputs has numbers assigned to string fields
     * (laptop_number: 3780021 should be '3780021', desk_number: 88003 should be '88003')
     */
    test.skip('new-user-onboarding-subflow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_fc629d4281d849bd913e1e454cb059bf.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        validateImports(fluentContent, ['Subflow', 'action', 'wfa', 'BooleanColumn', 'ReferenceColumn', 'StringColumn'])

        // ===== Subflow Definition =====
        expect(fluentContent).toContain('Subflow(')
        expect(fluentContent).toContain("name: 'New User Onboarding Subflow'")
        expect(fluentContent).toContain('Handles onboarding tasks')

        // ===== Inputs (2 reference columns) =====
        expect(fluentContent).toContain('inputs: {')
        expect(fluentContent).toContain('user_sys_id: ReferenceColumn')
        expect(fluentContent).toContain("label: 'User'")
        expect(fluentContent).toContain("referenceTable: 'sys_user'")
        expect(fluentContent).toContain('mandatory: true')

        expect(fluentContent).toContain('office_location: ReferenceColumn')
        expect(fluentContent).toContain("label: 'Office Location'")
        expect(fluentContent).toContain("referenceTable: 'cmn_location'")

        // ===== Outputs (2 boolean, 2 string) =====
        expect(fluentContent).toContain('outputs: {')
        expect(fluentContent).toContain('laptop_assigned: BooleanColumn')
        expect(fluentContent).toContain("label: 'Laptop Assigned'")

        expect(fluentContent).toContain('desk_assigned: BooleanColumn')
        expect(fluentContent).toContain("label: 'Desk Assigned'")

        expect(fluentContent).toContain('laptop_number: StringColumn')
        expect(fluentContent).toContain("label: 'Laptop Asset Number'")

        expect(fluentContent).toContain('desk_number: StringColumn')
        expect(fluentContent).toContain("label: 'Desk Asset Number'")

        // ===== Flow Variables (2 boolean, 2 string) =====
        expect(fluentContent).toContain('flowVariables: {')
        expect(fluentContent).toContain('laptop_assigned_flag: BooleanColumn')
        expect(fluentContent).toContain("label: 'Laptop Assignment Status'")

        expect(fluentContent).toContain('desk_assigned_flag: BooleanColumn')
        expect(fluentContent).toContain("label: 'Desk Assignment Status'")

        expect(fluentContent).toContain('laptop_asset_number: StringColumn')
        expect(fluentContent).toContain("label: 'Laptop Asset Number Storage'")

        expect(fluentContent).toContain('desk_asset_number: StringColumn')
        expect(fluentContent).toContain("label: 'Desk Asset Number Storage'")

        // ===== Action 1: lookUpRecord (user details) =====
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.lookUpRecord')
        expect(fluentContent).toContain("annotation: 'Retrieve user details for onboarding'")
        expect(fluentContent).toContain("table: 'sys_user'")
        expect(fluentContent).toContain("conditions: `sys_id=${wfa.dataPill(_params.inputs.user_sys_id, 'reference')}`")

        // ===== Action 2: sendNotification (welcome) =====
        expect(fluentContent).toContain('action.core.sendNotification')
        expect(fluentContent).toContain("annotation: 'Send welcome notification to new user'")
        expect(fluentContent).toContain("table_name: 'sys_user'")
        expect(fluentContent).toContain("record: wfa.dataPill(_params.inputs.user_sys_id, 'reference')")
        expect(fluentContent).toContain("notification: 'new_user_welcome_notification'")

        // ===== Action 3: lookUpRecord (available laptop) =====
        expect(fluentContent).toContain("annotation: 'Find first available laptop for assignment'")
        expect(fluentContent).toContain("table: 'alm_hardware'")
        expect(fluentContent).toContain('asset_tag!=NULL^assigned_to=NULL')

        // ===== If Logic 1: Check laptop availability =====
        expect(fluentContent).toContain('wfa.flowLogic.if(')
        expect(fluentContent).toContain("annotation: 'Check if available laptop exists'")
        expect(fluentContent).toMatch(
            /condition:\s*`\$\{wfa\.dataPill\([^)]+\.Record\.sys_id,\s*'reference'\)\}!=NULL`/
        )

        // ===== Action 4: updateRecord (assign laptop) =====
        expect(fluentContent).toContain('action.core.updateRecord')
        expect(fluentContent).toContain("annotation: 'Assign laptop to new user'")
        expect(fluentContent).toContain("table_name: 'alm_hardware'")
        expect(fluentContent).toContain('TemplateValue(')
        expect(fluentContent).toContain("assigned_to: wfa.dataPill(_params.inputs.user_sys_id, 'reference')")
        expect(fluentContent).toContain("install_status: '2'")
        expect(fluentContent).toContain("substatus: 'in_use'")

        // ===== Else Logic 1: No laptop available =====
        expect(fluentContent).toContain('wfa.flowLogic.else(')
        expect(fluentContent).toContain("annotation: 'Handle no laptop available scenario'")

        // ===== Action 5: log (no laptop) =====
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log that no laptop is available'")
        expect(fluentContent).toContain("log_level: 'warn'")
        expect(fluentContent).toContain('No available laptop found for user')
        expect(fluentContent).toContain('.Record.name')

        // ===== Action 6: lookUpRecord (available desk) =====
        expect(fluentContent).toContain("annotation: 'Find first available desk at office location'")
        expect(fluentContent).toContain("table: 'alm_asset'")
        expect(fluentContent).toContain('location=${wfa.dataPill(_params.inputs.office_location')

        // ===== If Logic 2: Check desk availability =====
        expect(fluentContent).toContain("annotation: 'Check if available desk exists at location'")
        expect(fluentContent).toMatch(
            /condition:\s*`\$\{wfa\.dataPill\([^)]+\.Record\.sys_id,\s*'reference'\)\}!=NULL`/
        )

        // ===== Action 7: updateRecord (assign desk) =====
        expect(fluentContent).toContain("annotation: 'Assign desk to new user at closest office location'")
        expect(fluentContent).toContain("table_name: 'alm_asset'")

        // ===== Else Logic 2: No desk available =====
        expect(fluentContent).toContain("annotation: 'Handle no desk available scenario'")

        // ===== Action 8: log (no desk) =====
        expect(fluentContent).toContain("annotation: 'Log that no desk is available at location'")
        expect(fluentContent).toContain('No available desk found at office location')

        // ===== Action 9: sendNotification (completion) =====
        expect(fluentContent).toContain("annotation: 'Send onboarding completion notification'")
        expect(fluentContent).toContain("notification: 'user_onboarding_complete_notification'")

        // ===== assignSubflowOutputs =====
        expect(fluentContent).toContain('wfa.flowLogic.assignSubflowOutputs(')
        expect(fluentContent).toContain("annotation: 'Assign subflow outputs with onboarding results'")
        expect(fluentContent).toContain('_params.outputs')
        expect(fluentContent).toContain('laptop_assigned:')
        expect(fluentContent).toContain('desk_assigned:')
        expect(fluentContent).toContain('laptop_number:')
        expect(fluentContent).toContain('desk_number:')

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        // Verify required record types exist
        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_variable']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_action_instance_v2']).toBeDefined()

        // ============================================================================
        // Step 4: Validate Subflow Record
        // ============================================================================
        const flows = mergedRecords['sys_hub_flow']
        expect(flows.length).toBeGreaterThanOrEqual(1)
        const subflow = flows.find((f: any) => f.name === 'New User Onboarding Subflow')
        expect(subflow).toBeDefined()
        expect(subflow.description).toContain('Handles onboarding tasks')
        expect(subflow.type).toBe('subflow')
        expect(subflow.generation_source).toBe('fluent')

        // ============================================================================
        // Step 5: Validate Inputs (2 reference columns)
        // ============================================================================
        const inputs = mergedRecords['sys_hub_flow_variable']?.filter(
            (v: any) => v.model_table === 'sys_hub_flow_input'
        )
        expect(inputs.length).toBeGreaterThanOrEqual(2)

        const userSysId = inputs.find((i: any) => i.element === 'user_sys_id')
        expect(userSysId).toBeDefined()
        expect(userSysId.label).toBe('User')
        expect(userSysId.internal_type).toBe('reference')
        expect(userSysId.reference).toBe('sys_user')
        expect(userSysId.mandatory).toBe(true)

        const officeLocation = inputs.find((i: any) => i.element === 'office_location')
        expect(officeLocation).toBeDefined()
        expect(officeLocation.label).toBe('Office Location')
        expect(officeLocation.internal_type).toBe('reference')
        expect(officeLocation.reference).toBe('cmn_location')
        expect(officeLocation.mandatory).toBe(true)

        // ============================================================================
        // Step 6: Validate Outputs (2 boolean, 2 string)
        // ============================================================================
        const outputs = mergedRecords['sys_hub_flow_variable']?.filter(
            (v: any) => v.model_table === 'sys_hub_flow_output'
        )
        expect(outputs.length).toBeGreaterThanOrEqual(4)

        const laptopAssigned = outputs.find((o: any) => o.element === 'laptop_assigned')
        expect(laptopAssigned).toBeDefined()
        expect(laptopAssigned.label).toBe('Laptop Assigned')
        expect(laptopAssigned.internal_type).toBe('boolean')

        const deskAssigned = outputs.find((o: any) => o.element === 'desk_assigned')
        expect(deskAssigned).toBeDefined()
        expect(deskAssigned.label).toBe('Desk Assigned')
        expect(deskAssigned.internal_type).toBe('boolean')

        const laptopNumber = outputs.find((o: any) => o.element === 'laptop_number')
        expect(laptopNumber).toBeDefined()
        expect(laptopNumber.label).toBe('Laptop Asset Number')
        expect(laptopNumber.internal_type).toBe('string')

        const deskNumber = outputs.find((o: any) => o.element === 'desk_number')
        expect(deskNumber).toBeDefined()
        expect(deskNumber.label).toBe('Desk Asset Number')
        expect(deskNumber.internal_type).toBe('string')

        // ============================================================================
        // Step 7: Validate Flow Variables (2 boolean, 2 string)
        // ============================================================================
        const flowVars = mergedRecords['sys_hub_flow_variable']?.filter((v: any) => v.model_table === 'sys_hub_flow')
        expect(flowVars.length).toBeGreaterThanOrEqual(4)

        const laptopAssignedFlag = flowVars.find((v: any) => v.element === 'laptop_assigned_flag')
        expect(laptopAssignedFlag).toBeDefined()
        expect(laptopAssignedFlag.label).toBe('Laptop Assignment Status')
        expect(laptopAssignedFlag.internal_type).toBe('boolean')

        const deskAssignedFlag = flowVars.find((v: any) => v.element === 'desk_assigned_flag')
        expect(deskAssignedFlag).toBeDefined()
        expect(deskAssignedFlag.label).toBe('Desk Assignment Status')
        expect(deskAssignedFlag.internal_type).toBe('boolean')

        const laptopAssetNumber = flowVars.find((v: any) => v.element === 'laptop_asset_number')
        expect(laptopAssetNumber).toBeDefined()
        expect(laptopAssetNumber.label).toBe('Laptop Asset Number Storage')
        expect(laptopAssetNumber.internal_type).toBe('string')

        const deskAssetNumber = flowVars.find((v: any) => v.element === 'desk_asset_number')
        expect(deskAssetNumber).toBeDefined()
        expect(deskAssetNumber.label).toBe('Desk Asset Number Storage')
        expect(deskAssetNumber.internal_type).toBe('string')

        // ============================================================================
        // Step 8: Validate Actions (9 actions total)
        // ============================================================================
        const actionInstances = mergedRecords['sys_hub_action_instance_v2']
        expect(actionInstances.length).toBeGreaterThanOrEqual(9)

        // Action 1: lookUpRecord (user details)
        const lookupUser = actionInstances.find((a: any) => a.comment?.includes('Retrieve user details'))
        expect(lookupUser).toBeDefined()
        const lookupUserValues = unzipInputArray(lookupUser.values) as any
        const lookupUserVar = (name: string) => findInput(lookupUserValues, name)?.value
        expect(lookupUserVar('table')).toBe('sys_user')
        expect(lookupUserVar('conditions')).toContain('sys_id')
        expect(lookupUserVar('conditions')).toContain('user_sys_id')

        // Action 2: sendNotification (welcome)
        const welcomeNotif = actionInstances.find((a: any) => a.comment?.includes('Send welcome notification'))
        expect(welcomeNotif).toBeDefined()
        const welcomeValues = unzipInputArray(welcomeNotif.values) as any
        const welcomeVar = (name: string) => findInput(welcomeValues, name)?.value
        expect(welcomeVar('table_name')).toBe('sys_user')
        expect(welcomeVar('notification')).toBe('new_user_welcome_notification')

        // Action 3: lookUpRecord (available laptop)
        const lookupLaptop = actionInstances.find((a: any) => a.comment?.includes('Find first available laptop'))
        expect(lookupLaptop).toBeDefined()
        const lookupLaptopValues = unzipInputArray(lookupLaptop.values) as any
        const lookupLaptopVar = (name: string) => findInput(lookupLaptopValues, name)?.value
        expect(lookupLaptopVar('table')).toBe('alm_hardware')
        expect(lookupLaptopVar('conditions')).toContain('asset_tag!=NULL')
        expect(lookupLaptopVar('conditions')).toContain('assigned_to=NULL')

        // Action 4: updateRecord (assign laptop)
        const assignLaptop = actionInstances.find((a: any) => a.comment?.includes('Assign laptop to new user'))
        expect(assignLaptop).toBeDefined()
        const assignLaptopValues = unzipInputArray(assignLaptop.values) as any
        const assignLaptopVar = (name: string) => findInput(assignLaptopValues, name)?.value
        expect(assignLaptopVar('table_name')).toBe('alm_hardware')
        expect(assignLaptopVar('values')).toContain('assigned_to')
        expect(assignLaptopVar('values')).toContain('install_status')

        // Action 5: log (no laptop)
        const logNoLaptop = actionInstances.find((a: any) => a.comment?.includes('Log that no laptop is available'))
        expect(logNoLaptop).toBeDefined()
        const logNoLaptopValues = unzipInputArray(logNoLaptop.values) as any
        const logNoLaptopVar = (name: string) => findInput(logNoLaptopValues, name)?.value
        expect(logNoLaptopVar('log_level')).toBe('warn')
        expect(logNoLaptopVar('log_message')).toContain('No available laptop found')

        // Action 6: lookUpRecord (available desk)
        const lookupDesk = actionInstances.find((a: any) => a.comment?.includes('Find first available desk'))
        expect(lookupDesk).toBeDefined()
        const lookupDeskValues = unzipInputArray(lookupDesk.values) as any
        const lookupDeskVar = (name: string) => findInput(lookupDeskValues, name)?.value
        expect(lookupDeskVar('table')).toBe('alm_asset')
        expect(lookupDeskVar('conditions')).toContain('location')

        // Action 7: updateRecord (assign desk)
        const assignDesk = actionInstances.find((a: any) => a.comment?.includes('Assign desk to new user'))
        expect(assignDesk).toBeDefined()
        const assignDeskValues = unzipInputArray(assignDesk.values) as any
        const assignDeskVar = (name: string) => findInput(assignDeskValues, name)?.value
        expect(assignDeskVar('table_name')).toBe('alm_asset')

        // Action 8: log (no desk)
        const logNoDesk = actionInstances.find((a: any) => a.comment?.includes('Log that no desk is available'))
        expect(logNoDesk).toBeDefined()
        const logNoDeskValues = unzipInputArray(logNoDesk.values) as any
        const logNoDeskVar = (name: string) => findInput(logNoDeskValues, name)?.value
        expect(logNoDeskVar('log_level')).toBe('warn')
        expect(logNoDeskVar('log_message')).toContain('No available desk found')

        // Action 9: sendNotification (completion)
        const completeNotif = actionInstances.find((a: any) => a.comment?.includes('Send onboarding completion'))
        expect(completeNotif).toBeDefined()
        const completeValues = unzipInputArray(completeNotif.values) as any
        const completeVar = (name: string) => findInput(completeValues, name)?.value
        expect(completeVar('notification')).toBe('user_onboarding_complete_notification')

        // ============================================================================
        // Step 9: Validate Flow Logic (2 if/else pairs + assignSubflowOutputs)
        // ============================================================================
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(5) // 2 if, 2 else, 1 assignSubflowOutputs

        // If logic: Check laptop availability
        const ifLaptop = flowLogicInstances.find((fl: any) => fl.comment?.includes('Check if available laptop exists'))
        expect(ifLaptop).toBeDefined()

        // Else logic: No laptop available
        const elseLaptop = flowLogicInstances.find((fl: any) => fl.comment?.includes('Handle no laptop available'))
        expect(elseLaptop).toBeDefined()

        // If logic: Check desk availability
        const ifDesk = flowLogicInstances.find((fl: any) => fl.comment?.includes('Check if available desk exists'))
        expect(ifDesk).toBeDefined()

        // Else logic: No desk available
        const elseDesk = flowLogicInstances.find((fl: any) => fl.comment?.includes('Handle no desk available'))
        expect(elseDesk).toBeDefined()

        // assignSubflowOutputs
        const assignOutputs = flowLogicInstances.find((fl: any) => fl.comment?.includes('Assign subflow outputs'))
        expect(assignOutputs).toBeDefined()
        const assignOutputsValues = unzipInputArray(assignOutputs.values) as any
        const assignOutputsVar = (name: string) =>
            assignOutputsValues.variables.find((v: any) => v.name === name)?.value
        expect(assignOutputsVar('laptop_assigned')).toBeDefined()
        expect(assignOutputsVar('desk_assigned')).toBeDefined()
        expect(assignOutputsVar('laptop_number')).toBeDefined()
        expect(assignOutputsVar('desk_number')).toBeDefined()
    })
})
